-- No key material or financial values are generated by a server migration.
ALTER TABLE household_datasets ADD COLUMN crypto_version INTEGER NOT NULL DEFAULT 0 CHECK(crypto_version IN (0,1));
-- Encrypted record IDs are opaque HMACs, including historical month IDs.
-- The browser validates the date cutoff after authenticated decryption.
DROP TRIGGER household_asset_cutoff_insert;
DROP TRIGGER household_asset_cutoff_update;
CREATE TRIGGER household_asset_cutoff_insert BEFORE INSERT ON household_records
WHEN NEW.kind IN ('historical','snapshots') AND json_extract(NEW.payload,'$.version') IS NOT 1
  AND (NEW.id<'2022-06' OR json_extract(NEW.payload,'$.month')<'2022-06' OR json_extract(NEW.payload,'$.date')<'2022-06-30')
BEGIN SELECT RAISE(ABORT,'household_asset_history_before_start'); END;
CREATE TRIGGER household_asset_cutoff_update BEFORE UPDATE ON household_records
WHEN NEW.kind IN ('historical','snapshots') AND json_extract(NEW.payload,'$.version') IS NOT 1
  AND (NEW.id<'2022-06' OR json_extract(NEW.payload,'$.month')<'2022-06' OR json_extract(NEW.payload,'$.date')<'2022-06-30')
BEGIN SELECT RAISE(ABORT,'household_asset_history_before_start'); END;
CREATE TABLE household_crypto_config (
  household_id TEXT PRIMARY KEY REFERENCES household_state(id),
  key_id TEXT NOT NULL UNIQUE,
  recovery_wrapped_key TEXT NOT NULL,
  recovery_public_key TEXT NOT NULL
);
CREATE TABLE household_crypto_vaults (
  credential_id TEXT PRIMARY KEY,
  identity_id TEXT NOT NULL,
  public_key_json TEXT NOT NULL,
  iv TEXT NOT NULL,
  ciphertext TEXT NOT NULL
);
CREATE TABLE household_crypto_grants (
  household_id TEXT NOT NULL REFERENCES household_crypto_config(household_id),
  credential_id TEXT NOT NULL REFERENCES household_crypto_vaults(credential_id),
  identity_id TEXT NOT NULL,
  service_link_id TEXT NOT NULL,
  wrapped_key TEXT NOT NULL,
  PRIMARY KEY(household_id,credential_id,service_link_id)
);
